insert into public.preview_catalogo_maestro_platos
  (plato_id, sinonimos, resumen, hack, que_observar, activo)
values
  ('papas-fritas', ARRAY['papas fritas', 'papa frita', 'fritas', 'bastones fritos']::text[], 'El clásico indiscutido. Aportan energía rápida por el almidón y el aceite de fritura, pero su carga lipídica es elevada y ralentiza el vaciado gástrico.', 'Escurrilas muy bien en papel absorbente antes de comerlas y evitá recalentarlas en microondas. Tip extra: sumales una pizca generosa de orégano o pimentón; además de sabor, aportan antioxidantes que ayudan a contrarrestar la oxidación de las grasas de fritura.', 'Registra la pesadez estomacal o el nivel de letargo post-comida en comparación con un acompañamiento al horno o hervido.', false),
  ('papas-horno', ARRAY['papas al horno', 'papa al horno', 'papas doradas']::text[], 'Una excelente alternativa a la fritura. Conservan el almidón de la papa y el carbohidrato de calidad, pero con un control de grasa infinitamente superior si se usa el aceite medido.', 'Cocinalas con piel (bien lavadas) para sumar fibra insoluble que mejora la respuesta glucémica. Tip extra: un toque de romero fresco y aceite de oliva antes de hornear no solo realza el perfil aromático, sino que protege los aceites a alta temperatura.', 'Compara tu nivel de saciedad y liviandad frente a las papas fritas tradicionales; vas a notar una digestión mucho más limpia.', false),
  ('pure-papa', ARRAY['puré de papa', 'pure de papa', 'puré de papas', 'pure de papas']::text[], 'Textura suave y de rápida asimilación. Al estar pisada, la papa predigiere parte del trabajo mecánico, lo que acelera la absorción de sus carbohidratos.', 'Si buscás modular el pico glucémico, preparalo con un toque de manteca real o aceite de oliva y evitá los lácteos ultraprocesados en exceso. Tip extra: una pizca de nuez moscada rallada en el momento estimula las secreciones gástricas y le da el toque clásico sin caer pesada.', 'Presta atención a la velocidad con la que reaparece el apetito; al ser un carbohidrato de absorción rápida, la saciedad puede durar un poco menos.', false),
  ('pure-zapallo', ARRAY['puré de zapallo', 'pure de zapallo', 'puré de calabaza', 'pure de calabaza']::text[], 'Una opción con mucha menor densidad calórica y mayor aporte de agua y fibra soluble. Ideal para dar volumen al plato sin sobrecargar carbohidratos.', 'Evitá excederte con el azúcar o manteca añadida; dejá que su dulzor natural brille solo. Tip extra: sumale una pizca de jengibre en polvo o pimienta negra para levantar la temperatura digestiva y cortar la acuosidad natural del zapallo.', 'Evalúa la liviandad absoluta con la que te levantás de la mesa; es un puré sumamente amigable para digestiones sensibles.', false),
  ('arroz-blanco', ARRAY['arroz blanco', 'arroz', 'arrocito', 'arroz parboil', 'arroz integral']::text[], 'Un carbohidrato noble, de fácil asimilación y bajísimo potencial alérgico. Excelente fuente de energía limpia para el sistema neuromuscular.', 'El gran secreto bio-hack del arroz: si lo cocinás y lo dejás enfriar unas horas en la heladera (arroz estacionado/frío), parte de su almidón se convierte en almidón resistente, el cual alimenta a tu microbiota y reduce el pico de glucosa. Alternativa económica de mejora: pasarte a arroz parboil o integral por casi el mismo costo te da un perfil de saciedad y rendimiento cognitivo superior sin altibajos de energía.', 'Nota cómo responde tu energía y tu abdomen al consumir arroz frío o recalentado frente al arroz recién hecho bien caliente.', false),
  ('arroz-primavera', ARRAY['arroz primavera', 'arroz con vegetales', 'arroz mixto']::text[], 'Una evolución del arroz blanco que incorpora fibras, color y micronutrientes gracias a los vegetales picados (zanahoria, arvejas, morrón).', 'Asegurate de que la porción de vegetales sea generosa en relación con el arroz para equilibrar la carga glucémica del plato. Tip extra: salpimentalo con provenzal o cúrcuma para sumar un golpe antiinflamatorio y potenciar el sabor de los vegetales.', 'Compara la saciedad prolongada de este arroz con vegetales frente al arroz blanco solo; la fibra extra cambia totalmente el tiempo de digestión.', false),
  ('fideos-pesto', ARRAY['fideos al pesto', 'pasta al pesto', 'tallarines al pesto']::text[], 'Combinación de pasta (carbohidrato energético) con una salsa viva a base de albahaca, ajo, nueces y aceite de oliva (grasas saludables y antioxidantes).', 'Prioriza la pasta al dente: la cocción justa mantiene una estructura de almidón más compacta que se digiere más lentamente. Alternativa accesible: usar fideos 100% de trigo candeal o integrales mejora notablemente la respuesta metabólica y evita la modorra mental típica de las harinas refinadas comunes.', 'Evalúa tu nivel de energía sostenida; las grasas buenas del pesto y el tipo de pasta ayudan a mantener la claridad mental post-almuerzo.', false),
  ('fideos-queso', ARRAY['fideos con queso', 'pasta con queso', 'fideos con manteca y queso']::text[], 'Confort food por excelencia. Alto contenido energético proveniente de la combinación de harinas refinadas y grasas lácteas.', 'No satures el plato con quesos industriales de rallar con exceso de sodio; opta por un queso de buena calidad fundido con el calor de la pasta recién escurrida. Tip extra: una pizca generosa de pimienta negra sobre el queso ayuda a estimular las enzimas necesarias para procesar los lácteos pesados.', 'Registra la velocidad de saciedad y la pesadez estomacal; es un plato denso que pide moderación en la porción si vas a seguir activo.', false),
  ('ensalada-verde', ARRAY['ensalada verde', 'ensalada mixta verde', 'hojas verdes', 'lechuga y rúcula']::text[], 'El pilar fundamental de la fibra viva. Aporta agua de vegetación, clorofila, vitaminas y minerales con un impacto calórico prácticamente nulo.', 'El orden de los factores altera el producto: comete esta ensalada verde antes del plato principal. Esa red de fibra crea una "malla" en el intestino que amortigua y ralentiza la absorción de los carbohidratos que vienen después. Tip extra: aderezala con abundante jugo de limón o vinagre de manzana y aceite de oliva; los ácidos orgánicos potencian la digestión gástrica.', 'Presta atención a tu saciedad inicial y a cómo se comporta tu tránsito intestinal al consumir vegetales crudos al inicio de la comida.', false),
  ('ensalada-rusa', ARRAY['ensalada rusa', 'papa y zanahoria con mayonesa']::text[], 'Combinación festiva de almidón (papas y zanahorias hervidas) unida por una emulsión lipídica (mayonesa).', 'Si podés, prepará una mayonesa casera rápida con aceite de oliva o rebajá la versión comercial con un toque de yogur natural o jugo de limón para aligerar la densidad grasa. Tip extra: un toque de perejil fresco picado arriba ayuda a refrescar el paladar y mitigar la pesadez de la mayonesa.', 'Nota la densidad del plato: opera casi como un plato principal por su aporte calórico, así que medí la porción si acompañá otra proteína pesada.', false),
  ('batatas', ARRAY['batatas', 'batata', 'camote', 'batatas al horno', 'batatas fritas']::text[], 'Una auténtica joya nutricional. Aporta carbohidratos de asimilación más lenta que la papa, combinados con betacarotenos y un perfil antioxidante superior.', 'Cocinalas al horno o al vapor con su piel; al caramelizarse levemente sus azúcares naturales, lográs un sabor increíble sin necesidad de agregar dulces artificiales. Tip extra: un toque de canela o jengibre rallado sobre la batata al horno eleva su perfil de sabor a otro nivel y mejora la sensibilidad a la insulina.', 'Compara la estabilidad de tu energía post-comida frente a la papa común; la batata suele dar una saciedad mucho más estable y duradera.', false),
  ('zapallo-coreano', ARRAY['zapallo coreano', 'zapallo anco', 'calabaza', 'zapallo', 'anco al horno']::text[], 'Versátil, dulce y de bajo impacto glucémico. Excelente fuente de fibra y antioxidantes protectores de la salud celular y visual.', 'Cortalo en cubos o rodajas y hacelo al horno con un toque de aceite de oliva hasta que los bordes queden tostados; eso concentra los azúcares naturales de manera perfecta. Tip extra: sumale pimentón ahumado o curry suave antes de hornear para lograr un contraste de sabores espectacular.', 'Registra la ligereza y el confort estomacal; es uno de los acompañamientos más nobles para mantener la panza chata y sin hinchazón.', false)
