-- Bloque 2: Acompañamientos (12 registros).
-- Insertar como inactivos para probar en Preview sin cambiar el comportamiento de producción.
-- En Preview, api/_catalogo-platos.js lee también las fichas inactivas.
-- En producción, el resolver sigue filtrando activo=true hasta aprobación explícita.
begin;
on conflict (plato_id) do update set
  sinonimos = excluded.sinonimos,
  resumen = excluded.resumen,
  hack = excluded.hack,
  que_observar = excluded.que_observar,
  updated_at = now();
commit;
